<script>
	import { onMount } from 'svelte';
	import { listMovements, decideMovement, startMovementReportReview, decideMovementReport, completeMovement } from '$lib/infrastructure/pocketbase/movements.js';
	let items = $state([]), loading = $state(true), error = $state(''), note = $state(''), pillar = $state('E'), sdgGoal = $state('12');
	async function load() { loading = true; error = ''; try { items = await listMovements(); } catch (e) { error = e.message; } finally { loading = false; } }
	async function movementDecision(id, decision) { try { await decideMovement(id, { decision, note, esgTags: decision === 'APPROVE' ? [{ pillar, sdgGoal: Number(sdgGoal) }] : [] }); note = ''; await load(); } catch (e) { error = e.message; } }
	async function reportDecision(id, decision) { try { await decideMovementReport(id, { decision, note }); note = ''; await load(); } catch (e) { error = e.message; } }
	async function start(id) { try { await startMovementReportReview(id); await load(); } catch (e) { error = e.message; } }
	async function complete(id) { try { await completeMovement(id); await load(); } catch (e) { error = e.message; } }
	onMount(load);
</script>
<style>
	section > div.border, article.border { border-color: transparent; box-shadow: 0 1px 3px rgb(15 23 42 / 0.08); }
</style>
<svelte:head><title>Verifikasi Gerakan | PFriends</title></svelte:head>
<section class="space-y-6"><header><p class="font-semibold text-emerald-700">Kendali mutu aksi lapangan</p><h1 class="text-3xl font-bold">Verifikasi Gerakan</h1><p class="mt-2 text-slate-600">Tinjau usulan, tetapkan tag ESG dan SDG, lalu periksa laporan aksi beserta buktinya.</p></header>{#if error}<p class="rounded-xl bg-red-50 p-4 text-red-800">{error}</p>{/if}<div class="grid gap-3 rounded-xl border bg-white p-4 md:grid-cols-3"><label>Catatan keputusan<input class="mt-1 w-full rounded-lg border p-2" bind:value={note} placeholder="Wajib untuk revisi atau penolakan"></label><label>Pilar ESG<select class="mt-1 w-full rounded-lg border p-2" bind:value={pillar}><option>E</option><option>S</option><option>G</option></select></label><label>Tujuan SDG<input class="mt-1 w-full rounded-lg border p-2" type="number" min="1" max="17" bind:value={sdgGoal}></label></div>{#if loading}<p>Memuat antrean...</p>{:else}<div class="space-y-5">{#each items as movement}<article class="rounded-2xl border bg-white p-5"><div class="flex flex-wrap items-start justify-between gap-3"><div><p class="text-xs font-bold text-emerald-700">{movement.category}</p><h2 class="text-xl font-bold">{movement.title}</h2><p class="mt-1 text-sm text-slate-600">{movement.leaderName} • {movement.region} • {movement.participantCount} peserta</p></div><span class="rounded-full bg-slate-100 px-3 py-1 text-xs font-bold">{movement.status}</span></div><p class="mt-3">{movement.description}</p>{#if movement.status === 'DIUSULKAN' || movement.status === 'PERLU_REVISI'}<div class="mt-4 flex flex-wrap gap-2"><button class="rounded-lg bg-emerald-700 px-3 py-2 text-white" onclick={() => movementDecision(movement.id, 'APPROVE')}>Setujui</button><button class="rounded-lg bg-amber-600 px-3 py-2 text-white" onclick={() => movementDecision(movement.id, 'REQUEST_REVISION')}>Minta revisi</button><button class="rounded-lg bg-red-700 px-3 py-2 text-white" onclick={() => movementDecision(movement.id, 'REJECT')}>Tolak</button></div>{/if}{#if movement.status === 'BERJALAN' && movement.approvedReportCount > 0}<button class="mt-4 rounded-lg bg-slate-900 px-3 py-2 text-white" onclick={() => complete(movement.id)}>Tandai selesai</button>{/if}{#if movement.reports?.length}<div class="mt-5 space-y-3 border-t pt-4"><h3 class="font-bold">Laporan aksi</h3>{#each movement.reports as report}<div class="rounded-xl bg-slate-50 p-4"><div class="flex justify-between gap-3"><b>{report.awardeeName} • {report.role}</b><span>{report.status}</span></div><p class="mt-2 text-sm">{report.activityDate.slice(0,10)} • {report.location} • {report.participantCount} peserta</p><p class="mt-2 text-sm">{report.outcomeNote}</p><p class="mt-2 text-xs font-semibold">{report.evidenceFiles.length} berkas bukti</p>{#if report.status === 'SUBMITTED'}<button class="mt-3 rounded-lg bg-blue-700 px-3 py-2 text-white" onclick={() => start(report.id)}>Mulai periksa</button>{/if}{#if report.status === 'SUBMITTED' || report.status === 'IN_REVIEW'}<div class="mt-3 flex flex-wrap gap-2"><button class="rounded-lg bg-emerald-700 px-3 py-2 text-white" onclick={() => reportDecision(report.id, 'APPROVE')}>Setujui laporan</button><button class="rounded-lg bg-amber-600 px-3 py-2 text-white" onclick={() => reportDecision(report.id, 'REQUEST_REVISION')}>Minta revisi</button><button class="rounded-lg bg-red-700 px-3 py-2 text-white" onclick={() => reportDecision(report.id, 'REJECT')}>Tolak</button></div>{/if}</div>{/each}</div>{/if}</article>{/each}</div>{/if}</section>
